import { FC, useEffect } from 'react';

import type OpenFin from '@openfin/core';

import { menuEvents } from '@common/utils/menu-window-provider';
import { navigate, Router, withRouter } from '@common/utils/router';
import { getUrlParams } from '@common/utils/router';

import { useCallbackOnAPIReady } from '@enterprise/hooks/useCallbackOnAPIReady';

interface Props {
    router: Router;
    children: React.ReactNode;
}

const MenuWindow: FC<Props> = ({ children, router }) => {
    useCallbackOnAPIReady(() => (fin.me as OpenFin.Window).close());

    useEffect(() => {
        // Allow escape key to close pop up window
        const handleKeyUp = (ev: KeyboardEvent) => {
            if (ev.key === 'Escape') {
                (fin.me as OpenFin.Window).blur();
            }
        };
        document.addEventListener('keyup', handleKeyUp);

        const handleUpdate = async (name: string, bounds: Partial<OpenFin.Bounds>, route: string) => {
            if (fin.me.name !== name) return;
            console.debug('MenuWindow: navigating window to route', route);
            // The below listener updates opacity to 1 after shown,
            await (fin.me as OpenFin.Window).once('shown', async () => {
                setTimeout(async () => {
                    await fin.me.updateOptions({ opacity: 1 });
                    const wOpts = await (fin.me as OpenFin.Window).getOptions();
                    // more details in WRK-2277
                    if (wOpts.opacity !== 1) {
                        await fin.me.updateOptions({ opacity: 1 });
                        console.debug('MenuWindow set opacity again', await fin.me.getOptions());
                    }
                });
            });
            await navigate(route);

            // restore child window in case it's minimized
            await (fin.me as OpenFin.Window).restore();
            await fin.me.show();
            await fin.me.focus();
        };
        menuEvents.addListener('update', handleUpdate);
        // On startup the update event gets sent before the listener is ready
        // This lets the window who created you know this menuWindow know it is up & ready
        menuEvents.emit('ready', fin.me.identity);

        return () => {
            document.removeEventListener('keyup', handleKeyUp);
            menuEvents.removeListener('update', handleUpdate);
        };
    }, []);

    useEffect(() => {
        const { title } = getUrlParams(router.asPath);
        document.title = title;
    }, [router]);

    return <>{children}</>;
};

export default withRouter(MenuWindow) as FC<{ children: React.ReactNode }>;
