import { FC } from 'react';

import type { AppProps } from 'next/app';

import App from '@common/pages/_app';

import { isFin } from '@common/utils/env';

import GlobalMenuWindowStyles from '@enterprise/components/ControlBar/MenuWindow/GlobalMenuWindowStyles';

import { BrowserContext } from '@common/hooks/context';

import MenuWindow from '../../ControlBar/MenuWindow/MenuWindow';
import BrowserThemeProvider from '../ThemeProvider/BrowserThemeProvider';

const MenuController: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    if (isFin && fin.me.isWindow) {
        return <MenuWindow>{children}</MenuWindow>;
    } else {
        // In a view popup
        return <>{children}</>;
    }
};

/**
 * Entry point for a callot page that is in a popup menu window.
 */
const BrowserPopupMenuApp: FC<AppProps> = (props) => {
    return (
        <BrowserContext>
            <BrowserThemeProvider>
                <GlobalMenuWindowStyles />
                <MenuController>
                    <App {...props} />
                </MenuController>
            </BrowserThemeProvider>
        </BrowserContext>
    );
};
export default BrowserPopupMenuApp;
